import{_ as a,o as e,c as r,a2 as l,j as t}from"./chunks/framework.D66Xq0Kv.js";const c=JSON.parse('{"title":"常用编程语言基础语法对比","description":"","frontmatter":{"title":"常用编程语言基础语法对比","date":"2026-10-27","categories":["编程语言","综合"],"tags":[]},"headers":[],"relativePath":"编程语言/常用编程语言基础语法对比.md","filePath":"编程语言/常用编程语言基础语法对比.md"}'),o={name:"编程语言/常用编程语言基础语法对比.md"};function h(n,d,i,p,s,b){return e(),r("div",null,[...d[0]||(d[0]=[l('<h1 id="常用编程语言基础语法对比" tabindex="-1">常用编程语言基础语法对比 <a class="header-anchor" href="#常用编程语言基础语法对比" aria-label="Permalink to &quot;常用编程语言基础语法对比&quot;">​</a></h1><h2 id="编译与运行" tabindex="-1">编译与运行 <a class="header-anchor" href="#编译与运行" aria-label="Permalink to &quot;编译与运行&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语言</th><th>编译与运行</th></tr></thead><tbody><tr><td>Java</td><td>javac Hello.java &amp; java Hello.class<br>java Hello.java （Java 11+）</td></tr><tr><td>Golang</td><td>go run hello.go<br>go build -o hello hello.go &amp; ./hello</td></tr><tr><td>Python</td><td>python hello.py</td></tr><tr><td>JS</td><td>node hello.js</td></tr><tr><td>TS</td><td>tsx hello.ts<br>tsx watch hello.ts<br>tsc &amp; node hello.js<br>node hello.ts</td></tr></tbody></table><h2 id="包管理器" tabindex="-1">包管理器 <a class="header-anchor" href="#包管理器" aria-label="Permalink to &quot;包管理器&quot;">​</a></h2><table tabindex="0"><thead><tr><th>语言</th><th>包管理器</th><th>元数据文件</th></tr></thead><tbody><tr><td>Java</td><td>Maven<br>Gradle</td><td>pom.xml<br>build.gradle | build.gradle.kts</td></tr><tr><td>Golang</td><td>Go Modules</td><td>go.mod &amp; go.sum</td></tr><tr><td>Python</td><td>pip<br>uv</td><td>requirements.txt<br>pyproject.toml &amp; uv.lock</td></tr><tr><td>JS / TS</td><td>npm</td><td>package.json</td></tr></tbody></table><h2 id="包与模块" tabindex="-1">包与模块 <a class="header-anchor" href="#包与模块" aria-label="Permalink to &quot;包与模块&quot;">​</a></h2><h3 id="包" tabindex="-1">包 <a class="header-anchor" href="#包" aria-label="Permalink to &quot;包&quot;">​</a></h3><p>包存在狭义与广义两种概念：</p><ul><li>狭义上，包指的是：语言内的代码组织单元，物理上常映射为目录。后续提到包这个概念时，如果不加特殊说明，一般是指狭义包。</li><li>广义上，包指的是：可分发、可安装、有版本的发布与依赖单元，物理载体通常是归档文件（jar、zip、wheel、tgz）。<a href="#包管理器">包管理器</a>中的包指代的就是广义包。</li></ul><table tabindex="0"><thead><tr><th>语言</th><th>狭义包</th><th>广义包</th></tr></thead><tbody><tr><td>Java</td><td><code>package</code>（目录）</td><td>jar、artifact、library、dependency</td></tr><tr><td>Golang</td><td><code>package</code>（目录）</td><td><code>module</code></td></tr><tr><td>Python</td><td>package （目录）</td><td>distribution package</td></tr><tr><td>JS / TS</td><td>无</td><td>npm package</td></tr></tbody></table><h3 id="模块" tabindex="-1">模块 <a class="header-anchor" href="#模块" aria-label="Permalink to &quot;模块&quot;">​</a></h3><p>在不同的编程语言中，模块的概念也有较大差异：</p><table tabindex="0"><thead><tr><th>语言</th><th>模块的含义</th></tr></thead><tbody><tr><td>Java</td><td>包的集合，部署与依赖单元（Java 9+）</td></tr><tr><td>Golang</td><td>包的集合，版本化依赖管理单元</td></tr><tr><td>Python</td><td>文件级代码单元，通常是一个源文件（ .py ）</td></tr><tr><td>JS / TS</td><td>文件级代码单元，通常是一个源文件（ .js / .ts ）</td></tr></tbody></table><p>对于 Java / Golang 来说，模块是包的集合，它们的关系是：模块 ⊃ 包（目录） ⊃ 文件。</p><p>对于 Python / JS / TS 来说，模块通常是一个源文件，它们的关系是：包（目录）⊃ 模块（文件）。这里为了便于类比理解，将包与目录等价了，但实际上 JS / TS 中不存在狭义包的概念，其与目录也并不等价。</p><h3 id="导入与导出" tabindex="-1">导入与导出 <a class="header-anchor" href="#导入与导出" aria-label="Permalink to &quot;导入与导出&quot;">​</a></h3><p>几乎所有编程语言都支持 import 其它<a href="#包">包</a>或<a href="#模块">模块</a>中的对象，大部分编程语言不需要显性 export 对象。如下所示：</p><table tabindex="0"><thead><tr><th>语言</th><th>import 的对象</th><th>export 的对象</th></tr></thead><tbody><tr><td>Java</td><td>类型（类、接口、枚举、注解）或静态成员</td><td>普通 java 文件无 export 关键字，通过修饰词控制可见性 <br>JPMS 可 exports 包来控制包的可见性</td></tr><tr><td>Golang</td><td>包</td><td>无 export 关键字，通过首字母大小写控制可见性</td></tr><tr><td>Python</td><td>模块、模块中的名称、包</td><td>无 export 关键字</td></tr><tr><td>JS / TS</td><td>export 的对象</td><td>变量、函数、类等</td></tr></tbody></table><p>示例：</p>',19),t("table",{tabindex:"0"},[t("thead",null,[t("tr",null,[t("th",null,"语言"),t("th",null,"import"),t("th",null,"export")])]),t("tbody",null,[t("tr",null,[t("td",null,"Java"),t("td",null,"import java.time.LocalDateTime"),t("td",null,"-")]),t("tr",null,[t("td",null,"Golang"),t("td",null,'import dt "time"'),t("td",null,"-")]),t("tr",null,[t("td",null,"Python"),t("td",null,"from datetime import datetime as dt"),t("td",null,"-")]),t("tr",null,[t("td",null,"JS / TS"),t("td",null,'import { DateTime as dt } from "luxon"'),t("td",{"css-module":"."},"export class DateTime")])])],-1)])])}const m=a(o,[["render",h]]);export{c as __pageData,m as default};
